mapper.select:
select deadline1.* from ( SELECT A.BUSI_DATE busiDate, A.MARKET_CODE marketCode, A.IS_HOLIDAY isHoliday, A.STATUS status, A.DEPT_CODE deptCode, row_number() over (partition by A.MARKET_CODE
order by A.BUSI_DATE desc
order by A.BUSI_DATE asc
) as num FROM CHB_MKT_HOLIDAY A
A.BUSI_DATE < STR_TO_DATE(#{holidayDate},'%Y-%m-%d')
A.BUSI_DATE > STR_TO_DATE(#{holidayDate},'%Y-%m-%d')
AND A.MARKET_CODE = #{marketCode,jdbcType=VARCHAR} AND A.STATUS = 'E' AND A.IS_HOLIDAY = '1'
) deadline1 where deadline1.num = #{days,jdbcType=INTEGER}

        SELECT DISTINCT LARGE_SH_DATE
		FROM REP_PROD_INFO_TA
		WHERE IS_LARGE_SH='1'
		AND LARGE_SH_DATE= #{NOW(), jdbcType=DATE}
		AND PROD_ID = #{prodId, jdbcType=VARCHAR}

  		 select 

	     	OPEN_DATE_END


	        OPEN_DATE_STR


	        OPEN_VDATE   

	     from REP_PRD_OPEN_SCHE
	     where PROD_ID = #{prodId, jdbcType=VARCHAR}
	     AND STATUS = 'E'

	     	AND OPEN_DATE_END = #{NOW(), jdbcType=DATE}


	        AND OPEN_DATE_STR = #{NOW(), jdbcType=DATE}


	        AND OPEN_VDATE = #{NOW(), jdbcType=DATE}

select deadline1.* from ( SELECT A.BUSI_DATE busiDate, A.MARKET_CODE marketCode, A.IS_HOLIDAY isHoliday, A.STATUS status, A.DEPT_CODE deptCode, row_number() over (partition by A.MARKET_CODE
order by A.BUSI_DATE asc
order by A.BUSI_DATE desc
) as num FROM CHB_MKT_HOLIDAY A
A.BUSI_DATE > STR_TO_DATE(#{holidayDate},'%Y-%m-%d')
A.BUSI_DATE < STR_TO_DATE(#{holidayDate},'%Y-%m-%d')
AND A.MARKET_CODE = #{marketCode,jdbcType=VARCHAR} AND A.STATUS = 'E' AND A.IS_HOLIDAY = '1'
) deadline1 where deadline1.num = #{days,jdbcType=INTEGER}
